    if !transfer(instruction.op) && index + 1 < code.count {
        result.append(index + 1)
    }
    if isJump(instruction.op), instruction.operands[0] < code.count, !result.contains(instruction.operands[0]) {
        result.append(instruction.operands[0])
    };
